/* Local font files served from public/fonts/ */
@font-face {
  font-family: "Noto Color Emoji";
  src: url("/fonts/noto/NotoColorEmoji.ttf") format("truetype");
  font-display: swap;
}
@font-face {
  font-family: "Lucida Console";
  src: url("/fonts/lucida_console/LucidaConsoleRegular.ttf") format("truetype");
  font-display: swap;
}
/* Fixed: name must match CSS class "Noto Sans Egyptian Hieroglyphs" */
/* Fixed: format must be "truetype" not "ttf" */
/* Fixed: path must start from /fonts/ not /public/fonts/ */
@font-face {
  font-family: "Noto Sans Egyptian Hieroglyphs";
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url("/fonts/noto/NotoSansEgyptianHieroglyphs-Regular.ttf") format("truetype");
  unicode-range: U+13000-1342E, U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+2000-206F, U+2074, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
