/* Stagger — each child waits (index - 1) × --oc-stagger before its transition or animation starts */
.stagger-30 {
  --oc-stagger: 30ms;
}

.stagger-60 {
  --oc-stagger: 60ms;
}

.stagger-100 {
  --oc-stagger: 100ms;
}

.stagger-150 {
  --oc-stagger: 150ms;
}

.stagger-250 {
  --oc-stagger: 250ms;
}

.delay-stagger {
  transition-delay: calc((sibling-index() - 1) * 60ms);
  transition-delay: calc((sibling-index() - 1) * var(--oc-stagger, 60ms));
}

.delay-stagger-reverse {
  transition-delay: calc((sibling-count() - sibling-index()) * 60ms);
  transition-delay: calc((sibling-count() - sibling-index()) * var(--oc-stagger, 60ms));
}

.animate-delay-stagger {
  animation-delay: calc((sibling-index() - 1) * 60ms);
  animation-delay: calc((sibling-index() - 1) * var(--oc-stagger, 60ms));
}

/* Fan — rotate siblings around the middle one, like cards in a hand (set on each child) */
.fan {
  rotate: calc((sibling-index() - (sibling-count() + 1) / 2) * 6deg);
  rotate: calc((sibling-index() - (sibling-count() + 1) / 2) * var(--oc-fan, 6deg));
  transform-origin: 50% 140%;
}

.fan-3 {
  --oc-fan: 3deg;
